package com.miniforce.controller;
import com.miniforce.dto.*; import com.miniforce.dto.AuthDtos.*; import com.miniforce.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;private final CurrentUser current;public AuthController(AuthService a,CurrentUser c){auth=a;current=c;}@PostMapping("/register") ResponseEntity<AuthResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(auth.register(r));}@PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);}@GetMapping("/me") UserResponse me(){return auth.me(current.require());}}
